@user = User.find_by(:display_name => params[:display_name])
if @user && (@user.visible? || current_user&.administrator?)
  @title = @user.display_name
else
  render_unknown_user

@user_block = UserBlock.new(:user => @user, :creator => current_user, :reason => params[:user_block][:reason], :created_at => Time.now.utc, :ends_at => Time.now.utc + @block_period.hours, :needs_view => params[:user_block][:needs_view])
@user_block.deactivates_at = @user_block.ends_at unless @user_block.needs_view
if @user_block.save

@report = current_user.reports.new(report_params)
@report.issue = Issue.create_with(:assigned_role => default_assigned_role).find_or_initialize_by(issue_params)
if @report.save
  @report.issue.assigned_role = "administrator" if default_assigned_role == "administrator"
  @report.issue.reopen unless @report.issue.open?
  @report.issue.save!
  @report.issue.reported_user&.spam_check

@message.from_user_visible = false if @message.sender == current_user
@message.to_user_visible = false if @message.recipient == current_user
if @message.save

if @message.recipient == current_user || @message.sender == current_user
  @message.message_read = true if @message.recipient == current_user
  @message.save

if message.recipient == current_user
  message.update(:message_read => true)
  @message = Message.new(:recipient => message.sender, :title => "Re: #{message.title}")

if current_user.id == @message.from_user_id
  @message.from_user_visible = false
elsif current_user.id == @message.to_user_id
  @message.to_user_visible = false
end
@message.save!

